
create extension if not exists pgcrypto;
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;

create table public.organizations(id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, base_currency char(3) not null default 'GBP', timezone text not null default 'Europe/London', vat_rate_percent numeric(5,2) not null default 20, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', phone text, is_active boolean not null default true, two_factor_enabled boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.permissions(id uuid primary key default gen_random_uuid(), code text not null unique, description text not null default '');
create table public.roles(id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id) on delete cascade, code text not null, name text not null, is_system boolean not null default false, created_at timestamptz not null default now(), unique nulls not distinct(organization_id,code));
create table public.role_permissions(role_id uuid not null references public.roles(id) on delete cascade, permission_id uuid not null references public.permissions(id) on delete cascade, primary key(role_id,permission_id));
create table public.clients_3pl(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, company_name text not null, code text not null, contact_email text, contact_phone text, billing_address jsonb not null default '{}', billing_period text not null default 'MONTHLY' check(billing_period in('WEEKLY','MONTHLY')), account_status text not null default 'ACTIVE' check(account_status in('ACTIVE','SUSPENDED')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,code), unique(organization_id,external_id));
create table public.organization_members(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role_id uuid not null references public.roles(id), client_3pl_id uuid references public.clients_3pl(id) on delete set null, is_active boolean not null default true, invited_by uuid references public.profiles(id), joined_at timestamptz not null default now(), unique(organization_id,user_id));
create table public.user_invitations(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, email text not null, role_id uuid not null references public.roles(id), token_hash text not null unique, invited_by uuid references public.profiles(id), expires_at timestamptz not null, accepted_at timestamptz, created_at timestamptz not null default now());
create table public.rate_cards(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, name text not null, pick_fee_minor bigint not null default 0, pack_fee_minor bigint not null default 0, extra_item_fee_minor bigint not null default 0, storage_pallet_per_month_minor bigint not null default 0, storage_shelf_per_month_minor bigint not null default 0, storage_bin_per_month_minor bigint not null default 0, minimum_monthly_charge_minor bigint not null default 0, currency char(3) not null default 'GBP', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,external_id));
alter table public.clients_3pl add column rate_card_id uuid references public.rate_cards(id) on delete set null;

create table public.marketplace_accounts(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, name text not null, marketplace text not null check(marketplace in('EBAY_UK','EBAY_US','EBAY_DE','OTHER')), seller_username text, auth_status text not null default 'DISCONNECTED', environment text not null default 'PRODUCTION', last_sync_at timestamptz, last_sync_status text, last_sync_message text, token_expires_at timestamptz, auto_sync_interval_minutes int not null default 30, is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,external_id));
create table public.marketplace_credentials(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, marketplace_account_id uuid not null unique references public.marketplace_accounts(id) on delete cascade, access_token_ciphertext text, refresh_token_ciphertext text, encryption_key_version text, scopes text[] not null default '{}', expires_at timestamptz, updated_at timestamptz not null default now());
create table public.marketplace_sync_runs(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, marketplace_account_id uuid not null references public.marketplace_accounts(id) on delete cascade, started_at timestamptz not null default now(), completed_at timestamptz, status text not null default 'IN_PROGRESS', orders_fetched int not null default 0, orders_imported int not null default 0, orders_skipped_duplicate int not null default 0, exceptions_raised int not null default 0, log_message text);
create table public.marketplace_exceptions(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, marketplace_account_id uuid references public.marketplace_accounts(id) on delete set null, exception_type text not null, source text not null, reference_id text not null, details text not null, raw_payload_snippet text, status text not null default 'PENDING', created_at timestamptz not null default now(), resolved_at timestamptz, resolved_by uuid references public.profiles(id), resolution_note text);
create table public.product_categories(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, parent_id uuid references public.product_categories(id), unique(organization_id,name));
create table public.products(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, sku text not null, name text not null, barcode text, dimensions_cm jsonb not null default '{}', weight_kg numeric(12,3), owner_type text not null default 'OPERATOR', client_3pl_id uuid references public.clients_3pl(id), status text not null default 'ACTIVE', cost_price_minor bigint not null default 0, selling_price_minor bigint not null default 0, currency char(3) not null default 'GBP', low_stock_threshold int not null default 0, reorder_level int not null default 0, category_id uuid references public.product_categories(id), category_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,sku), unique(organization_id,external_id));
create table public.marketplace_sku_mappings(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, marketplace_account_id uuid not null references public.marketplace_accounts(id) on delete cascade, external_sku text not null, external_listing_id text, listing_title text, is_verified boolean not null default false, created_at timestamptz not null default now(), unique(marketplace_account_id,external_sku));
create table public.customers(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, name text not null, email text, phone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,external_id));
create table public.customer_addresses(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, customer_id uuid not null references public.customers(id) on delete cascade, address_type text not null default 'SHIPPING', recipient_name text, street text, city text, county text, postal_code text, country_code char(2), is_default boolean not null default false);
create table public.orders(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, order_number text not null, marketplace_account_id uuid references public.marketplace_accounts(id), external_order_id text, customer_id uuid references public.customers(id), sales_source text not null default 'MANUAL', owner_type text not null default 'OPERATOR', client_3pl_id uuid references public.clients_3pl(id), customer_name text not null, customer_email text, shipping_address jsonb not null default '{}', status text not null default 'New', payment_state text not null default 'PENDING', total_minor bigint not null default 0, tax_minor bigint not null default 0, shipping_charge_minor bigint not null default 0, shipping_cost_minor bigint, currency char(3) not null default 'GBP', carrier text, tracking_number text, raw_payload jsonb, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,order_number), unique(organization_id,external_id), unique(marketplace_account_id,external_order_id));
create table public.order_items(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id), sku text not null, product_name text not null, quantity int not null check(quantity>0), unit_price_minor bigint not null, tax_amount_minor bigint not null default 0, total_price_minor bigint not null, is_backordered boolean not null default false, reserved_quantity int not null default 0);
create table public.order_status_history(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, order_id uuid not null references public.orders(id) on delete cascade, from_status text, to_status text not null, changed_by uuid references public.profiles(id), note text, changed_at timestamptz not null default now());
create table public.order_shipments(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, order_id uuid not null references public.orders(id) on delete cascade, carrier text, service_level text, tracking_number text, parcel_weight_kg numeric(12,3), shipping_cost_minor bigint, shipped_at timestamptz, delivered_at timestamptz, status text not null default 'PENDING');
create table public.warehouses(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, name text not null, code text not null, address jsonb not null default '{}', is_active boolean not null default true, created_at timestamptz not null default now(), unique(organization_id,code), unique(organization_id,external_id));
create table public.warehouse_locations(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, warehouse_id uuid not null references public.warehouses(id) on delete cascade, zone text, aisle text, shelf text, bin text, location_code text not null, location_type text not null default 'BIN', capacity_units int not null default 0, is_active boolean not null default true, unique(warehouse_id,location_code));
create table public.stock_ledger(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, product_id uuid not null references public.products(id), location_id uuid references public.warehouse_locations(id), client_3pl_id uuid references public.clients_3pl(id), quantity_delta int not null, stock_state text not null, source_type text not null, source_id uuid, unit_cost_minor bigint, note text, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table public.stock_adjustments(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, adjustment_number text not null, product_id uuid not null references public.products(id), location_id uuid references public.warehouse_locations(id), quantity_delta int not null, target_state text not null, reason_code text not null, note text, requested_by uuid references public.profiles(id), requires_approval boolean not null default false, status text not null default 'PENDING_APPROVAL', approved_by uuid references public.profiles(id), approval_note text, evaluated_value_minor bigint not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,adjustment_number));
create table public.suppliers(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, name text not null, code text not null, contact_name text, email text, phone text, payment_terms_days int not null default 0, currency char(3) not null default 'GBP', lead_time_days int not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,code), unique(organization_id,external_id));
create table public.purchase_orders(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, po_number text not null, supplier_id uuid not null references public.suppliers(id), status text not null default 'DRAFT', subtotal_minor bigint not null default 0, tax_minor bigint not null default 0, total_minor bigint not null default 0, currency char(3) not null default 'GBP', notes text, expected_date date, created_by uuid references public.profiles(id), approved_by uuid references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,po_number), unique(organization_id,external_id));
create table public.purchase_order_items(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, purchase_order_id uuid not null references public.purchase_orders(id) on delete cascade, product_id uuid not null references public.products(id), sku text not null, product_name text not null, ordered_qty int not null, received_qty int not null default 0, unit_cost_minor bigint not null, total_cost_minor bigint not null);
create table public.goods_receipts(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, receipt_number text not null, purchase_order_id uuid not null references public.purchase_orders(id), received_by uuid references public.profiles(id), received_at timestamptz not null default now(), discrepancy_note text, unique(organization_id,receipt_number));
create table public.goods_receipt_items(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, goods_receipt_id uuid not null references public.goods_receipts(id) on delete cascade, product_id uuid not null references public.products(id), location_id uuid references public.warehouse_locations(id), received_qty int not null default 0, shortage_qty int not null default 0, damaged_qty int not null default 0);
create table public.returns(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, return_number text not null, order_id uuid not null references public.orders(id), reason_code text not null, status text not null default 'OPEN', refund_amount_minor bigint, refund_status text, created_at timestamptz not null default now(), inspected_at timestamptz, unique(organization_id,return_number), unique(organization_id,external_id));
create table public.return_items(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, return_id uuid not null references public.returns(id) on delete cascade, product_id uuid not null references public.products(id), sku text not null, quantity int not null, disposition text, notes text);
create table public.storage_snapshots(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, client_3pl_id uuid not null references public.clients_3pl(id), snapshot_date date not null, occupied_pallets numeric(12,2) not null default 0, occupied_shelves numeric(12,2) not null default 0, occupied_bins numeric(12,2) not null default 0, estimated_cost_minor bigint not null default 0, currency char(3) not null default 'GBP', unique(client_3pl_id,snapshot_date));
create table public.invoices(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, invoice_number text not null, invoice_type text not null, recipient_type text not null, recipient_id uuid, recipient_name text not null, issue_date date not null, due_date date not null, subtotal_minor bigint not null default 0, vat_rate_percent numeric(5,2) not null default 0, vat_amount_minor bigint not null default 0, total_minor bigint not null default 0, paid_amount_minor bigint not null default 0, currency char(3) not null default 'GBP', status text not null default 'DRAFT', void_reason text, is_immutable boolean not null default false, created_by uuid references public.profiles(id), created_at timestamptz not null default now(), unique(organization_id,invoice_number), unique(organization_id,external_id));
create table public.invoice_items(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, invoice_id uuid not null references public.invoices(id) on delete cascade, description text not null, quantity numeric(14,3) not null default 1, unit_price_minor bigint not null, total_minor bigint not null);
create table public.payments(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, payment_number text not null, amount_minor bigint not null check(amount_minor>0), currency char(3) not null default 'GBP', payment_method text not null, payment_date date not null, reference text, payer_name text, unallocated_credit_minor bigint not null default 0, recorded_by uuid references public.profiles(id), created_at timestamptz not null default now(), unique(organization_id,payment_number), unique(organization_id,external_id));
create table public.payment_allocations(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, payment_id uuid not null references public.payments(id) on delete cascade, invoice_id uuid not null references public.invoices(id), amount_minor bigint not null check(amount_minor>0), unique(payment_id,invoice_id));
create table public.expenses(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, expense_number text not null, category text not null, supplier_name text, expense_date date not null, amount_minor bigint not null, vat_minor bigint not null default 0, currency char(3) not null default 'GBP', allocated_to text, status text not null default 'PENDING_APPROVAL', approved_by uuid references public.profiles(id), note text, created_at timestamptz not null default now(), unique(organization_id,expense_number), unique(organization_id,external_id));
create table public.chart_of_accounts(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, account_code text not null, account_name text not null, account_type text not null, currency char(3), is_active boolean not null default true, unique(organization_id,account_code));
create table public.journal_entries(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, entry_number text not null, entry_date date not null, source_type text not null, source_id uuid, description text, status text not null default 'DRAFT', idempotency_key text, created_by uuid references public.profiles(id), posted_at timestamptz, created_at timestamptz not null default now(), unique(organization_id,entry_number), unique(organization_id,idempotency_key));
create table public.journal_entry_lines(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, journal_entry_id uuid not null references public.journal_entries(id) on delete cascade, account_id uuid not null references public.chart_of_accounts(id), debit_minor bigint not null default 0 check(debit_minor>=0), credit_minor bigint not null default 0 check(credit_minor>=0), description text, check((debit_minor>0 and credit_minor=0) or (credit_minor>0 and debit_minor=0)));
create table public.marketplace_payouts(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, external_id text, payout_reference text not null, marketplace_account_id uuid not null references public.marketplace_accounts(id), total_sales_minor bigint not null default 0, total_fees_minor bigint not null default 0, refunds_minor bigint not null default 0, shipping_adjustments_minor bigint not null default 0, other_adjustments_minor bigint not null default 0, net_payout_minor bigint not null default 0, currency char(3) not null default 'GBP', payout_date timestamptz not null, status text not null, transaction_id text, bank_deposit_status text not null default 'PENDING', bank_reference text, notes text, created_at timestamptz not null default now(), unique(organization_id,payout_reference), unique(organization_id,external_id));
create table public.payout_orders(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, payout_id uuid not null references public.marketplace_payouts(id) on delete cascade, order_id uuid not null references public.orders(id), unique(payout_id,order_id));
create table public.bank_transactions(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, bank_account_name text, transaction_date date not null, amount_minor bigint not null, currency char(3) not null, reference text, description text, external_transaction_id text, imported_at timestamptz not null default now(), unique(organization_id,external_transaction_id));
create table public.financial_reconciliations(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, period text not null, marketplace_account_id uuid references public.marketplace_accounts(id), expected_payout_minor bigint not null default 0, actual_payout_minor bigint not null default 0, difference_minor bigint not null default 0, unmatched_transactions_count int not null default 0, status text not null, last_reconciled_at timestamptz, reconciled_by uuid references public.profiles(id), audit_notes text, breakdown jsonb not null default '{}', created_at timestamptz not null default now());
create table public.packaging_jobs(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, job_number text not null, client_3pl_id uuid references public.clients_3pl(id), job_date timestamptz not null default now(), packaging_type text not null, quantity int not null default 1, material_cost_minor bigint not null default 0, service_charge_minor bigint not null default 0, total_charge_minor bigint not null default 0, status text not null default 'IN_PROGRESS', invoice_id uuid references public.invoices(id), order_id uuid references public.orders(id), performed_by uuid references public.profiles(id), notes text, unique(organization_id,job_number));
create table public.shipping_jobs(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, dispatch_id text not null, client_3pl_id uuid references public.clients_3pl(id), job_date timestamptz not null default now(), carrier text not null, tracking_number text, service_level text, parcel_weight_kg numeric(12,3), carrier_cost_minor bigint not null default 0, service_charge_minor bigint not null default 0, total_charge_minor bigint not null default 0, status text not null default 'IN_TRANSIT', invoice_id uuid references public.invoices(id), order_id uuid references public.orders(id), destination jsonb not null default '{}', unique(organization_id,dispatch_id));
create table public.dropshipping_calculations(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, product_id uuid references public.products(id), sku text not null, product_name text not null, supplier_name text, purchase_cost_minor bigint not null default 0, supplier_cost_minor bigint not null default 0, shipping_cost_minor bigint not null default 0, packaging_cost_minor bigint not null default 0, additional_expenses_minor bigint not null default 0, selling_price_minor bigint not null default 0, marketplace_fee_percent numeric(7,4) not null default 0, marketplace_fee_minor bigint not null default 0, other_costs_minor bigint not null default 0, shipping_option text not null, shipping_charged_to_customer_minor bigint not null default 0, total_cost_minor bigint not null default 0, gross_profit_minor bigint not null default 0, margin_percent numeric(9,4) not null default 0, net_profit_minor bigint not null default 0, currency char(3) not null default 'GBP', updated_by uuid references public.profiles(id), updated_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid references public.profiles(id), notification_type text not null, title text not null, message text not null, severity text not null default 'INFO', reference_url text, is_read boolean not null default false, is_dismissed boolean not null default false, created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, actor_id uuid references public.profiles(id), action text not null, entity text not null, entity_id text not null, before_snapshot jsonb, after_snapshot jsonb, notes text, created_at timestamptz not null default now());
create table public.system_settings(id uuid primary key default gen_random_uuid(), organization_id uuid not null unique references public.organizations(id) on delete cascade, base_currency char(3) not null default 'GBP', business_timezone text not null default 'Europe/London', default_vat_rate_percent numeric(5,2) not null default 20, adjustment_approval_threshold_value_minor bigint not null default 5000, adjustment_approval_threshold_quantity int not null default 10, allow_negative_stock boolean not null default false, auto_sync_enabled boolean not null default true, updated_at timestamptz not null default now());
create table public.import_jobs(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, job_type text not null, status text not null default 'QUEUED', source_file_name text, total_rows int not null default 0, processed_rows int not null default 0, error_report jsonb, created_by uuid references public.profiles(id), created_at timestamptz not null default now(), completed_at timestamptz);
create table public.export_jobs(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, export_type text not null, status text not null default 'QUEUED', filters jsonb not null default '{}', file_path text, created_by uuid references public.profiles(id), created_at timestamptz not null default now(), completed_at timestamptz);

