on conflict(code) do nothing;
insert into public.roles(organization_id,code,name,is_system) values
(null,'SUPER_ADMIN','Super Admin',true),(null,'OPS_MANAGER','Operations Manager',true),(null,'WAREHOUSE_STAFF','Warehouse Staff',true),(null,'FINANCE_USER','Finance User',true),(null,'CLIENT_USER','Client User',true),(null,'VIEWER','Viewer',true)
on conflict do nothing;
insert into public.role_permissions(role_id,permission_id)
select r.id,p.id from public.roles r cross join public.permissions p
where r.organization_id is null and (
r.code='SUPER_ADMIN'
or (r.code='OPS_MANAGER' and p.code in('dashboard.view','orders.view','orders.create','orders.edit','products.view','products.create','products.edit','inventory.view','inventory.adjust','inventory.manage','marketplace.view','marketplace.manage','purchasing.view','purchasing.manage','returns.view','returns.manage','fulfilment.view','fulfilment.manage','reports.view','reports.export'))
or (r.code='WAREHOUSE_STAFF' and p.code in('dashboard.view','orders.view','products.view','inventory.view','inventory.adjust','fulfilment.view','fulfilment.manage'))
or (r.code='FINANCE_USER' and p.code in('dashboard.view','orders.view','finance.view','finance.manage','reports.view','reports.export'))
or (r.code='CLIENT_USER' and p.code in('dashboard.view','orders.view','products.view','inventory.view','fulfilment.view','finance.view'))
or (r.code='VIEWER' and p.code in('dashboard.view','orders.view','products.view','inventory.view','reports.view'))
) on conflict do nothing;

create or replace function public.is_org_member(org uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$
select exists(select 1 from public.organization_members m where m.organization_id=org and m.user_id=auth.uid() and m.is_active);
$$;
create or replace function public.has_org_permission(org uuid, perm text) returns boolean language sql stable security definer set search_path=public,pg_temp as $$
select exists(select 1 from public.organization_members m join public.roles r on r.id=m.role_id left join public.role_permissions rp on rp.role_id=r.id left join public.permissions p on p.id=rp.permission_id where m.organization_id=org and m.user_id=auth.uid() and m.is_active and (r.code='SUPER_ADMIN' or p.code=perm));
$$;
grant execute on function public.is_org_member(uuid) to authenticated;
grant execute on function public.has_org_permission(uuid,text) to authenticated;

alter table public.organizations enable row level security;
create policy org_read_member on public.organizations for select to authenticated using(public.is_org_member(id));
create policy org_update_admin on public.organizations for update to authenticated using(public.has_org_permission(id,'organization.manage')) with check(public.has_org_permission(id,'organization.manage'));
alter table public.profiles enable row level security;
create policy profile_self_read on public.profiles for select to authenticated using(id=auth.uid());
create policy profile_self_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
alter table public.permissions enable row level security;
create policy permissions_read on public.permissions for select to authenticated using(true);
alter table public.roles enable row level security;
create policy roles_read on public.roles for select to authenticated using(organization_id is null or public.is_org_member(organization_id));
create policy roles_manage on public.roles for all to authenticated using(organization_id is not null and public.has_org_permission(organization_id,'users.manage')) with check(organization_id is not null and public.has_org_permission(organization_id,'users.manage'));
alter table public.role_permissions enable row level security;
create policy role_permissions_read on public.role_permissions for select to authenticated using(true);
alter table public.organization_members enable row level security;
create policy members_read on public.organization_members for select to authenticated using(public.is_org_member(organization_id));
create policy members_manage on public.organization_members for all to authenticated using(public.has_org_permission(organization_id,'users.manage')) with check(public.has_org_permission(organization_id,'users.manage'));
alter table public.user_invitations enable row level security;
create policy invitations_manage on public.user_invitations for all to authenticated using(public.has_org_permission(organization_id,'users.manage')) with check(public.has_org_permission(organization_id,'users.manage'));

do $$
declare t text;
begin
 foreach t in array array['clients_3pl','rate_cards','marketplace_accounts','marketplace_credentials','marketplace_sync_runs','marketplace_exceptions','product_categories','products','marketplace_sku_mappings','customers','customer_addresses','orders','order_items','order_status_history','order_shipments','warehouses','warehouse_locations','stock_ledger','stock_adjustments','suppliers','purchase_orders','purchase_order_items','goods_receipts','goods_receipt_items','returns','return_items','storage_snapshots','invoices','invoice_items','payments','payment_allocations','expenses','chart_of_accounts','journal_entries','journal_entry_lines','marketplace_payouts','payout_orders','bank_transactions','financial_reconciliations','packaging_jobs','shipping_jobs','dropshipping_calculations','notifications','audit_logs','system_settings','import_jobs','export_jobs'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('create policy %I on public.%I for select to authenticated using(public.is_org_member(organization_id))',t||'_org_select',t);
  if t not in('stock_ledger','journal_entries','journal_entry_lines','audit_logs') then
   execute format('create policy %I on public.%I for insert to authenticated with check(public.is_org_member(organization_id))',t||'_org_insert',t);
   execute format('create policy %I on public.%I for update to authenticated using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id))',t||'_org_update',t);
   execute format('create policy %I on public.%I for delete to authenticated using(public.is_org_member(organization_id))',t||'_org_delete',t);
  end if;
 end loop;
end $$;

create index idx_members_user on public.organization_members(user_id,is_active);
create index idx_products_org_status on public.products(organization_id,status);
create index idx_orders_org_created on public.orders(organization_id,created_at desc);
create index idx_orders_org_status on public.orders(organization_id,status);
create index idx_order_items_order on public.order_items(order_id);
create index idx_stock_ledger_product_date on public.stock_ledger(organization_id,product_id,created_at desc);
create index idx_invoices_org_due on public.invoices(organization_id,due_date,status);
create index idx_payments_org_date on public.payments(organization_id,payment_date desc);
create index idx_journal_org_date on public.journal_entries(organization_id,entry_date desc);
create index idx_audit_org_entity on public.audit_logs(organization_id,entity,entity_id,created_at desc);
create index idx_notifications_unread on public.notifications(organization_id,user_id,is_read,created_at desc);
